mapper.insert:
insert into goods (type_id, name, price, num, description, image, details, status, create_time, update_time)
VALUES (#{typeId},#{name},#{price},#{num},#{description},#{image}
,#{details},#{status},#{createTime},#{updateTime})

mapper.update:
update goods
name = #{name}, type_id = #{typeId}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, num = #{num}, details = #{details},
where id = #{id}

mapper.select:
select g.* , g.description as shortDesc,c.style_name as categoryName from goods g left join goods_category_style c on c.id = g.type_id
and g.status = #{status}
and g.name like concat('%',#{name},'%')
and g.type_id = #{categoryId}
order by g.create_time desc

SELECT t.* FROM ( SELECT g.*, g.description as shortDesc,c.style_name as categoryName FROM goods g LEFT JOIN goods_category_style c ON c.id = g.type_id
AND g.status = 1
ORDER BY RAND() ) AS t LIMIT 4;
